@Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        String authorization = request.getHeader(CommonConstant.TOKEN);

        if (isBlank(authorization) || "null".equals(authorization)) {
            log.info("No Authorization, PASS");
            return true;
        }

        try {
            // 判断该请求，是否是商户
            boolean isMerchant = request.getRequestURI().contains(CommonConstant.MERCHANT_FLAG);

            // 针对认证对象，进行校验
            UserDTO userDTO = authenticate(authorization, isMerchant);
            // 对于认证通过的对象，放入上下文中
            log.info("token has been authenticated: token {}, user:{}", authorization, JSON.toJSONString(userDTO));
            RequestHolder.addUser(userDTO);
            return true;
        } catch (Exception failed) {
            SecurityContextHolder.clearContext();
            log.warn("token authorization exception, token:{}", authorization, failed);
            request.setAttribute("filter.error", failed);
            request.getRequestDispatcher(CommonConstant.ERROR_CONTROLLER).forward(request, response);
        }
        return false;
    }

private UserDTO authenticate(String token, boolean isMerchant) {
        return isMerchant ? getMerchant(token) : getUser(token);
    }

private UserDTO getUser(String token) {
        // 获取用户基本信息
        PassportDTO info = clientService.getBaseInfo(token);
        log.info("userInfo is {}, with token is {} and threadId is {} and threadName is {}", info, token, Thread.currentThread().getId(), Thread.currentThread().getName());

        if (info == null || StringUtils.isBlank(info.getUserId())) {
            return null;
        }

        return new UserDTO(info.getUserId(), info.getAliasValue());
    }

@Override
    public PassportDTO getBaseInfo(String token) {
        notBlank("token is required!");

        TokenExPassportDto tokenExPassportDto = externalClientService.passportInfo(token);

        return new ClientAssembler().from(tokenExPassportDto);
    }

@Override
    public TokenExPassportDto passportInfo(String token) {
        notBlank(token, "token is required!");

        try {
            HttpHeaders headers = new HttpHeaders();
            headers.add("token", token);

            UriComponentsBuilder uriComponentsBuilder = UriComponentsBuilder.fromHttpUrl(clientUrl + PASSPORT_INFO);

            HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(headers);

            ResponseEntity<GenericResponse<TokenExPassportDto>> response = clientRestTemplate.exchange(
                    uriComponentsBuilder.toUriString(), HttpMethod.GET, requestEntity,
                    new ParameterizedTypeReference<GenericResponse<TokenExPassportDto>>() {
                    });
            if (response == null || response.getBody() == null || response.getStatusCodeValue() != HttpStatus.SC_OK) {
                throw new ExternalReportException("passportInfo is null, token is " + token);
            }

            return response.getBody().getData();
        } catch (Exception e) {
            log.error("passportInfo encountered Exception, with token is {}", token, e);
            throw new ExternalReportException("passportInfo encountered Exception, with token is " + token);
        }
    }

